from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class SshTunnelDetails(SchemaObject):
    dist_name = SchemaField(name='dist_name', not_null=True)
    port = SchemaField(name='port', not_null=True)

    def __init__(self, dist_name, port):
        self.dist_name = dist_name
        self.port = port

        super(SshTunnelDetails, self).__init__()


class GetSshTunnelConfigDetail(SchemaObject):
    config_type = SchemaField(name='config_type', not_null=True)
    details = SchemaField(name='details', not_null=True, many=True, klass=SshTunnelDetails)

    def __init__(self, config_type, details):
        self.config_type = config_type
        self.details = details

        super(GetSshTunnelConfigDetail, self).__init__()
